 import { fileURLToPath } from 'node:url';
 export const db = new Database(fileURLToPath(new URL('./data.db', import.meta.url)));
 db.pragma('journal_mode = WAL');
+db.exec(
+  `CREATE TABLE IF NOT EXISTS applications (
+    id INTEGER PRIMARY KEY AUTOINCREMENT,
+    name TEXT NOT NULL DEFAULT '',
+    email TEXT NOT NULL DEFAULT '',
+    track TEXT NOT NULL DEFAULT '',
+    statement TEXT NOT NULL DEFAULT '',
+    status TEXT NOT NULL DEFAULT 'draft'
+  )`
+);
+try {
+  const cols = db.prepare(`PRAGMA table_info(applications)`).all() as { name: string }[];
+  const have = new Set(cols.map((c) => c.name));
+  if (!have.has('name')) db.exec(`ALTER TABLE applications ADD COLUMN name TEXT NOT NULL DEFAULT ''`);
+  if (!have.has('email')) db.exec(`ALTER TABLE applications ADD COLUMN email TEXT NOT NULL DEFAULT ''`);
+  if (!have.has('track')) db.exec(`ALTER TABLE applications ADD COLUMN track TEXT NOT NULL DEFAULT ''`);
+  if (!have.has('statement')) db.exec(`ALTER TABLE applications ADD COLUMN statement TEXT NOT NULL DEFAULT ''`);
+  if (!have.has('status')) db.exec(`ALTER TABLE applications ADD COLUMN status TEXT NOT NULL DEFAULT 'draft'`);
+} catch {
+  // ignore migration errors; table already created above
+}

