@@ -1,5 +1,56 @@
 import express from 'express';
+import { db } from './db.js';
 const app = express();
 app.use(express.json());
 app.get('/api/health', (_req, res) => { res.json({ ok: true }); });
+
+type Row = { id: number; name: string; email: string; track: string; statement: string; status: string };
+function toJson(r: Row) {
+  return { id: r.id, name: r.name ?? '', email: r.email ?? '', track: r.track ?? '', statement: r.statement ?? '', status: r.status === 'submitted' ? 'submitted' : 'draft' };
+}
+function isStringRecord(body: unknown): body is { name: string; email: string; track: string; statement: string } {
+  if (typeof body !== 'object' || body === null) return false;
+  const b = body as Record<string, unknown>;
+  return typeof b.name === 'string' && typeof b.email === 'string' && typeof b.track === 'string' && typeof b.statement === 'string';
+}
+const EMAIL_RE = /^\S+@\S+\.\S+$/;
+function validForSubmit(name: string, email: string, track: string, statement: string): boolean {
+  if (name.trim() === '') return false;
+  if (!EMAIL_RE.test(email.trim())) return false;
+  if (track !== 'Design' && track !== 'Engineering') return false;
+  if (statement.trim().length < 10) return false;
+  return true;
+}
+app.get('/api/applications', (_req, res) => {
+  const rows = db.prepare('SELECT id, name, email, track, statement, status FROM applications ORDER BY id ASC').all() as Row[];
+  res.json(rows.map(toJson));
+});
+app.post('/api/applications', (req, res) => {
+  if (!isStringRecord(req.body)) { res.status(400).json({ error: 'invalid fields' }); return; }
+  const info = db.prepare('INSERT INTO applications (name, email, track, statement, status) VALUES (?, ?, ?, ?, ?)').run(req.body.name, req.body.email, req.body.track, req.body.statement, 'draft');
+  const row = db.prepare('SELECT id, name, email, track, statement, status FROM applications WHERE id = ?').get(Number(info.lastInsertRowid)) as Row;
+  res.status(201).json(toJson(row));
+});
+app.put('/api/applications/:id', (req, res) => {
+  if (!isStringRecord(req.body)) { res.status(400).json({ error: 'invalid fields' }); return; }
+  const id = Number(req.params.id);
+  if (!Number.isInteger(id)) { res.status(404).json({ error: 'not found' }); return; }
+  const row = db.prepare('SELECT id, name, email, track, statement, status FROM applications WHERE id = ?').get(id) as Row | undefined;
+  if (!row) { res.status(404).json({ error: 'not found' }); return; }
+  if (row.status === 'submitted') { res.status(409).json({ error: 'already submitted' }); return; }
+  db.prepare('UPDATE applications SET name = ?, email = ?, track = ?, statement = ? WHERE id = ?').run(req.body.name, req.body.email, req.body.track, req.body.statement, id);
+  const updated = db.prepare('SELECT id, name, email, track, statement, status FROM applications WHERE id = ?').get(id) as Row;
+  res.json(toJson(updated));
+});
+app.post('/api/applications/:id/submit', (req, res) => {
+  const id = Number(req.params.id);
+  if (!Number.isInteger(id)) { res.status(404).json({ error: 'not found' }); return; }
+  const row = db.prepare('SELECT id, name, email, track, statement, status FROM applications WHERE id = ?').get(id) as Row | undefined;
+  if (!row) { res.status(404).json({ error: 'not found' }); return; }
+  if (row.status === 'submitted') { res.status(409).json({ error: 'already submitted' }); return; }
+  if (!validForSubmit(row.name ?? '', row.email ?? '', row.track ?? '', row.statement ?? '')) { res.status(400).json({ error: 'invalid application' }); return; }
+  db.prepare("UPDATE applications SET status = 'submitted' WHERE id = ?").run(id);
+  const updated = db.prepare('SELECT id, name, email, track, statement, status FROM applications WHERE id = ?').get(id) as Row;
+  res.json(toJson(updated));
+});
 app.listen(Number(process.env.BACKEND_PORT), '127.0.0.1');

--- a/frontend/src/App.tsx
+++ b/frontend/src/App.tsx
@@ -1 +1,225 @@
-export default function App() { return <main><h1>Ready to build</h1></main>; }
+import { useEffect, useState } from 'react';
+
+type AppRecord = { id: number; name: string; email: string; track: string; statement: string; status: 'draft' | 'submitted' };
+
+const EMAIL_RE = /^\S+@\S+\.\S+$/;
+
+export default function App() {
+  const [step, setStep] = useState(1);
+  const [name, setName] = useState('');
+  const [email, setEmail] = useState('');
+  const [track, setTrack] = useState('');
+  const [statement, setStatement] = useState('');
+  const [draftId, setDraftId] = useState<number | null>(null);
+  const [error, setError] = useState('');
+  const [status, setStatus] = useState('');
+  const [submitted, setSubmitted] = useState<AppRecord[]>([]);
+
+  useEffect(() => {
+    let cancelled = false;
+    fetch('/api/applications')
+      .then((r) => (r.ok ? r.json() : []))
+      .then((all: AppRecord[]) => {
+        if (cancelled) return;
+        const list = Array.isArray(all) ? all : [];
+        const drafts = list.filter((a) => a.status === 'draft');
+        if (drafts.length > 0) {
+          const latest = drafts.reduce((a, b) => (a.id > b.id ? a : b));
+          setName(latest.name ?? '');
+          setEmail(latest.email ?? '');
+          setTrack(latest.track ?? '');
+          setStatement(latest.statement ?? '');
+          setDraftId(latest.id);
+        }
+        setSubmitted(list.filter((a) => a.status === 'submitted'));
+      })
+      .catch(() => {});
+    return () => { cancelled = true; };
+  }, []);
+
+  function step1Error(): string {
+    if (name.trim() === '') return 'Enter your full name.';
+    if (!EMAIL_RE.test(email.trim())) return 'Enter a valid email address.';
+    return '';
+  }
+
+  function step2Error(): string {
+    if (track !== 'Design' && track !== 'Engineering') return 'Select a valid track.';
+    if (statement.trim().length < 10) return 'Statement must be at least 10 characters.';
+    return '';
+  }
+
+  function handleNextFromStep1() {
+    const msg = step1Error();
+    if (msg) { setError(msg); return; }
+    setError('');
+    setStep(2);
+  }
+
+  function handleNextFromStep2() {
+    const msg = step2Error();
+    if (msg) { setError(msg); return; }
+    setError('');
+    setStep(3);
+  }
+
+  function handleBack() {
+    setError('');
+    setStep((s) => Math.max(1, s - 1));
+  }
+
+  async function persistDraft(): Promise<AppRecord | null> {
+    const payload = { name, email, track, statement };
+    try {
+      if (draftId === null) {
+        const res = await fetch('/api/applications', {
+          method: 'POST',
+          headers: { 'Content-Type': 'application/json' },
+          body: JSON.stringify(payload),
+        });
+        if (!res.ok) return null;
+        const data = (await res.json()) as AppRecord;
+        setDraftId(data.id);
+        return data;
+      }
+      const res = await fetch(`/api/applications/${draftId}`, {
+        method: 'PUT',
+        headers: { 'Content-Type': 'application/json' },
+        body: JSON.stringify(payload),
+      });
+      if (res.status === 409) {
+        const retry = await fetch('/api/applications', {
+          method: 'POST',
+          headers: { 'Content-Type': 'application/json' },
+          body: JSON.stringify(payload),
+        });
+        if (!retry.ok) return null;
+        const data = (await retry.json()) as AppRecord;
+        setDraftId(data.id);
+        return data;
+      }
+      if (!res.ok) return null;
+      const data = (await res.json()) as AppRecord;
+      return data;
+    } catch {
+      return null;
+    }
+  }
+
+  async function handleSaveDraft() {
+    setError('');
+    const saved = await persistDraft();
+    if (saved) {
+      setStatus('Draft saved');
+    } else {
+      setError('Could not save draft.');
+    }
+  }
+
+  async function refreshSubmitted() {
+    try {
+      const res = await fetch('/api/applications');
+      if (!res.ok) return;
+      const all = (await res.json()) as AppRecord[];
+      setSubmitted(all.filter((a) => a.status === 'submitted'));
+    } catch {
+      // ignore
+    }
+  }
+
+  async function handleSubmit() {
+    setError('');
+    const msg1 = step1Error();
+    const msg2 = step2Error();
+    const msg = msg1 || msg2;
+    if (msg) { setError(msg); return; }
+    const saved = await persistDraft();
+    if (!saved) { setError('Could not save application.'); return; }
+    try {
+      const res = await fetch(`/api/applications/${saved.id}/submit`, { method: 'POST' });
+      if (res.ok) {
+        setStatus('Application submitted');
+        setDraftId(null);
+        await refreshSubmitted();
+        return;
+      }
+      if (res.status === 409) {
+        setError('Application already submitted.');
+        return;
+      }
+      setError('Application is invalid.');
+    } catch {
+      setError('Could not submit application.');
+    }
+  }
+
+  return (
+    <main>
+      <h1>Application form</h1>
+      {error ? <div role="alert">{error}</div> : null}
+      <div role="status">{status}</div>
+      {step === 1 ? (
+        <div>
+          <div>
+            <label htmlFor="full-name">Full name</label>
+            <input id="full-name" value={name} onChange={(e) => setName(e.target.value)} />
+          </div>
+          <div>
+            <label htmlFor="email">Email</label>
+            <input id="email" value={email} onChange={(e) => setEmail(e.target.value)} />
+          </div>
+          <div>
+            <button type="button" onClick={handleNextFromStep1}>Next</button>
+          </div>
+        </div>
+      ) : null}
+      {step === 2 ? (
+        <div>
+          <div>
+            <label htmlFor="track">Track</label>
+            <select id="track" value={track} onChange={(e) => setTrack(e.target.value)}>
+              <option value="">Select a track</option>
+              <option value="Design">Design</option>
+              <option value="Engineering">Engineering</option>
+            </select>
+          </div>
+          <div>
+            <label htmlFor="statement">Statement</label>
+            <textarea id="statement" value={statement} onChange={(e) => setStatement(e.target.value)} />
+          </div>
+          <div>
+            <button type="button" onClick={handleBack}>Back</button>
+            <button type="button" onClick={handleNextFromStep2}>Next</button>
+          </div>
+        </div>
+      ) : null}
+      {step === 3 ? (
+        <div>
+          <div role="region" aria-label="Review">
+            <p>Full name: {name}</p>
+            <p>Email: {email}</p>
+            <p>Track: {track}</p>
+            <p>Statement: {statement}</p>
+          </div>
+          <div>
+            <button type="button" onClick={handleBack}>Back</button>
+            <button type="button" onClick={handleSubmit}>Submit application</button>
+          </div>
+        </div>
+      ) : null}
+      <div>
+        <button type="button" onClick={handleSaveDraft}>Save draft</button>
+      </div>
+      <section>
+        <h2>Submitted applications</h2>
+        <ul aria-label="Submitted applications">
+          {submitted.map((a) => (
+            <li key={a.id}>
+              {a.name} — {a.email} — {a.track} — {a.statement}
+            </li>
+          ))}
+        </ul>
+      </section>
+    </main>
+  );
+}

