+type NoteRow = { id: number; title: string; body: string };
 app.get('/api/health', (_req, res) => { res.json({ ok: true }); });
+app.get('/api/notes', (_req, res) => {
+  const rows = db.prepare('SELECT id, title, body FROM notes ORDER BY id ASC').all() as NoteRow[];
+  res.json(rows);
+});
+app.post('/api/notes', (req, res) => {
+  const payload = req.body as unknown;
+  const title = (payload as { title?: unknown } | null | undefined)?.title;
+  const body = (payload as { body?: unknown } | null | undefined)?.body;
+  if (typeof title !== 'string' || typeof body !== 'string') {
+    res.status(400).json({ error: 'Invalid note' });
+    return;
+  }
+  const trimmed = title.trim();
+  if (!trimmed) {
+    res.status(400).json({ error: 'Invalid note' });
+    return;
+  }
+  const info = db.prepare('INSERT INTO notes (title, body) VALUES (?, ?)').run(trimmed, body);
+  const row = db.prepare('SELECT id, title, body FROM notes WHERE id = ?').get(Number(info.lastInsertRowid)) as NoteRow;
+  res.status(201).json(row);
+});
+app.patch('/api/notes/:id', (req, res) => {
+  const id = Number(req.params.id);
+  if (!Number.isInteger(id)) {
+    res.status(404).json({ error: 'Not found' });
+    return;
+  }
+  const existing = db.prepare('SELECT id, title, body FROM notes WHERE id = ?').get(id) as NoteRow | undefined;
+  if (!existing) {
+    res.status(404).json({ error: 'Not found' });
+    return;
+  }
+  const payload = req.body as unknown;
+  if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) {
+    res.status(400).json({ error: 'Invalid patch' });
+    return;
+  }
+  const record = payload as Record<string, unknown>;
+  const hasTitle = Object.prototype.hasOwnProperty.call(record, 'title');
+  const hasBody = Object.prototype.hasOwnProperty.call(record, 'body');
+  if (!hasTitle && !hasBody) {
+    res.status(400).json({ error: 'Invalid patch' });
+    return;
+  }
+  let nextTitle = existing.title;
+  let nextBody = existing.body;
+  if (hasTitle) {
+    if (typeof record.title !== 'string') {
+      res.status(400).json({ error: 'Invalid patch' });
+      return;
+    }
+    const trimmed = record.title.trim();
+    if (!trimmed) {
+      res.status(400).json({ error: 'Invalid patch' });
+      return;
+    }
+    nextTitle = trimmed;
+  }
+  if (hasBody) {
+    if (typeof record.body !== 'string') {
+      res.status(400).json({ error: 'Invalid patch' });
+      return;
+    }
+    nextBody = record.body;
+  }
+  db.prepare('UPDATE notes SET title = ?, body = ? WHERE id = ?').run(nextTitle, nextBody, id);
+  const updated = db.prepare('SELECT id, title, body FROM notes WHERE id = ?').get(id) as NoteRow;
+  res.json(updated);
+});
 app.listen(Number(process.env.BACKEND_PORT), '127.0.0.1');

