+  if (typeof input !== 'string') throw new Error('Invalid CSV');
+  let csv = input;
+  if (csv.endsWith('\r\n')) csv = csv.slice(0, -2);
+  else if (csv.endsWith('\n')) csv = csv.slice(0, -1);
