+  const opt1 = typeof rawOptions[1] === 'string' ? (rawOptions[1] as string).trim() : '';
+  if (!opt0 || !opt1) {
+    res.status(400).json({ error: 'Invalid options' });
+    return;
+  }
+  if (rawCorrect !== 0 && rawCorrect !== 1) {
+    res.status(400).json({ error: 'Invalid correctIndex' });
+    return;
+  }
+  const result = db
+    .prepare('INSERT INTO questions (prompt, option_a, option_b, correct_index) VALUES (?, ?, ?, ?)')
+    .run(prompt, opt0, opt1, rawCorrect);
+  const id = Number(result.lastInsertRowid);
+  res.status(201).json({ id, prompt, options: [opt0, opt1], correctIndex: rawCorrect });
+});
+
+app.post('/api/grade', (req, res) => {
+  const body = (req.body ?? {}) as Record<string, unknown>;
+  const answers = body['answers'];
+  if (!Array.isArray(answers)) {
+    res.status(400).json({ error: 'Invalid answers' });
+    return;
+  }
+  if (answers.length === 0) {
+    res.json({ correct: 0, total: 0 });
+    return;
+  }
+  const seen = new Set<number>();
+  for (const entry of answers) {
+    if (typeof entry !== 'object' || entry === null) {
+      res.status(400).json({ error: 'Invalid answer' });
+      return;
+    }
+    const rec = entry as Record<string, unknown>;
+    const id = rec['id'];
+    const choice = rec['choice'];
+    if (typeof id !== 'number' || !Number.isInteger(id)) {
+      res.status(400).json({ error: 'Invalid id' });
+      return;
+    }
+    if (choice !== 0 && choice !== 1) {
+      res.status(400).json({ error: 'Invalid choice' });
+      return;
+    }
+    if (seen.has(id)) {
+      res.status(400).json({ error: 'Duplicate id' });
+      return;
+    }
+    seen.add(id);
+  }
+  const rows = db.prepare('SELECT id, correct_index FROM questions').all() as { id: number; correct_index: number }[];
+  const correctById = new Map<number, number>();
+  for (const r of rows) correctById.set(r.id, r.correct_index);
+  for (const id of seen) {
+    if (!correctById.has(id)) {
+      res.status(400).json({ error: 'Unknown id' });
+      return;
+    }
+  }
+  let correct = 0;
+  for (const entry of answers) {
+    const rec = entry as { id: number; choice: number };
+    if (correctById.get(rec.id) === rec.choice) correct += 1;
+  }
+  res.json({ correct, total: answers.length });
+});
